#include <bits/stdc++.h>
using namespace std;

long long fastExp(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MAX = 5005;
    long long S[MAX][MAX];
    long long mod = 998244353;

    // Initialize Stirling numbers of the second kind
    for (int i = 0; i <= 5000; i++) {
        for (int j = 0; j <= i; j++) {
            S[i][j] = 0;
        }
    }
    S[1][1] = 1;
    S[0][0] = 0;
    for (int i = 1; i <= 5000; i++) {
        S[i][i] = 1;
        S[i][0] = 0;
    }
    for (int i = 2; i <= 5000; i++) {
        for (int j = 1; j <= i; j++) {
            S[i][j] = (S[i - 1][j] * j % mod + S[i - 1][j - 1]) % mod;
        }
    }

    long long n, m;
    int k;
    cin >> n >> m >> k;

    m = fastExp(m, mod - 2, mod); // modular inverse of m

    vector<long long> dp(MAX, 0);
    dp[0] = 1;
    for (int i = 1; i <= min(n, (long long)k); i++) {
        dp[i] = (dp[i - 1] * (n - i + 1)) % mod;
    }

    long long result = 0;
    for (int i = 1; i <= min(n, (long long)k); i++) {
        long long term = dp[i] * fastExp(m, i, mod) % mod;
        term = term * S[k][i] % mod;
        result = (result + term) % mod;
    }

    cout << result << "\n";

    return 0;
}
